package pilots;
import java.io.*;import java.lang.reflect.*;import java.security.*;
/** Compare non-sequential restore frames against independent source WAV-free fixtures. */
public final class SeekExactTest {
 public static void main(String[] args)throws Exception{BufferedReader rows=new BufferedReader(new FileReader(args[0]));Field pixels=AnimationClip.class.getDeclaredField("pixels");pixels.setAccessible(true);String line;int frames=0,clips=0;AnimationClip a=null;String previous="";while((line=rows.readLine())!=null){String[] parts=line.split(",");if(!parts[0].equals(previous)){if(a!=null)a.close();a=new AnimationClip("/"+parts[0]);previous=parts[0];clips++;}int target=Integer.parseInt(parts[1]);a.seek(target);if(a.index!=target)throw new Exception("Wrong seek index");MessageDigest hash=MessageDigest.getInstance("SHA-256");ByteArrayOutputStream meta=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(meta);out.writeShort(a.offsetX);out.writeShort(a.offsetY);out.writeShort(a.width);out.writeShort(a.height);hash.update(meta.toByteArray());hash.update((byte[])pixels.get(a),0,a.width*a.height);String sha="";for(byte b:hash.digest())sha+=Integer.toHexString((b&255)|256).substring(1);if(!sha.equals(parts[2]))throw new Exception("Seek pixels changed "+line);frames++;}if(a!=null)a.close();System.out.println("Non-sequential seek: source-exact frames="+frames+" clips="+clips);}
}
